import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';

import { UserRoleSelect } from './user-role-select';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

export const UsersList = () => {
  const usersQuery = useUsers();
  const updateRoleMutation = useUpdateUserRole();

  const handleRoleChange = (userId: string, role: 'ADMIN' | 'USER') => {
    updateRoleMutation.mutate({ userId, data: { role } });
  };

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }: { entry: User }) {
            return (
              <UserRoleSelect user={entry} onRoleChange={handleRoleChange} />
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { useNotifications } from '@/components/ui/notifications';
import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export const updateUserRole = ({
  userId,
  data,
}: {
  userId: string;
  data: UpdateUserRoleInput;
}) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();
  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (_data, variables) => {
      // Update the users list in the cache immediately to show the new role
      queryClient.setQueryData(getUsersQueryOptions().queryKey, (old) => {
        if (!old) return old;
        return {
          ...old,
          data: old.data.map((user: any) =>
            user.id === variables.userId
              ? { ...user, role: variables.role }
              : user
          ),
        };
      });

      // Show success message
      useNotifications.getState().addNotification({
        type: 'success',
        title: 'Success',
        message: 'User role updated successfully',
      });

      onSuccess?.(_data, variables);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};

