import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { User } from '@/types/api';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';

import { UserRoleSelect } from './user-role-select';
import { useUpdateUserRole } from '../api/update-user-role';

import { DeleteUser } from './delete-user';

export const UsersList = () => {
  const usersQuery = useUsers();
  const updateRoleMutation = useUpdateUserRole();

  const handleRoleChange = (userId: string, role: 'ADMIN' | 'USER') => {
    updateRoleMutation.mutate({ userId, data: { role } });
  };

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }: { entry: User }) {
            return (
              <UserRoleSelect user={entry} onRoleChange={handleRoleChange} />
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { z } from 'zod';

import { useNotifications } from '@/components/ui/notifications';
import { api } from '@/lib/api-client';
import { MutationConfig } from '@/lib/react-query';
import { getUsersQueryOptions } from './get-users';

export const updateUserRoleInputSchema = z.object({
  role: z.enum(['ADMIN', 'USER']),
});

export type UpdateUserRoleInput = z.infer<typeof updateUserRoleInputSchema>;

export const updateUserRole = ({
  userId,
  data,
}: {
  userId: string;
  data: UpdateUserRoleInput;
}) => {
  return api.patch(`/users/${userId}/role`, data);
};

type UseUpdateUserRoleOptions = {
  mutationConfig?: MutationConfig<typeof updateUserRole>;
};

export const useUpdateUserRole = ({
  mutationConfig,
}: UseUpdateUserRoleOptions = {}) => {
  const queryClient = useQueryClient();
  const { onSuccess, ...restConfig } = mutationConfig || {};

  return useMutation({
    onSuccess: (_data, variables) => {
      // Update the users list in the cache immediately to show the new role
      queryClient.setQueryData(getUsersQueryOptions().queryKey, (old) => {
        if (!old) return old;
        return {
          ...old,
          data: old.data.map((user: any) =>
            user.id === variables.userId
              ? { ...user, role: variables.role }
              : user
          ),
        };
      });

      // Show success message
      useNotifications.getState().addNotification({
        type: 'success',
        title: 'Success',
        message: 'User role updated successfully',
      });

      onSuccess?.(_data, variables);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};

import { Check, ChevronDown } from 'lucide-react';
import { useEffect, useState } from 'react';

import { User } from '@/types/api';

type UserRoleSelectProps = {
  user: User;
  onRoleChange: (userId: string, role: 'ADMIN' | 'USER') => void;
};

const ROLES = [
  { value: 'ADMIN', label: 'Admin' },
  { value: 'USER', label: 'User' },
] as const;

export const UserRoleSelect = ({ user, onRoleChange }: UserRoleSelectProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const [currentRole, setCurrentRole] = useState(user.role);

  useEffect(() => {
    setCurrentRole(user.role);
  }, [user.role]);

  const handleRoleChange = (newRole: 'ADMIN' | 'USER') => {
    setCurrentRole(newRole);
    setIsOpen(false);
    onRoleChange(user.id, newRole);
  };

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        className="flex min-h-[28px] w-32 items-center justify-between rounded-md bg-gray-50 px-2 text-sm text-gray-700 ring-1 ring-gray-300 transition-colors hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
      >
        <span>{ROLES.find((r) => r.value === currentRole)?.label}</span>
        <ChevronDown className="ml-1 h-4 w-4 text-gray-400" />
      </button>

      {isOpen && (
        <>
          <div
            className="fixed inset-0 z-10"
            onClick={() => setIsOpen(false)}
          />
          <div className="absolute right-0 z-20 mt-1 w-32 rounded-md bg-white py-1 shadow-lg ring-1 ring-gray-300 focus:outline-none">
            {ROLES.map((role) => (
              <div
                key={role.value}
                className={`flex cursor-pointer items-center px-3 py-2 text-sm ${
                  currentRole === role.value
                    ? 'bg-blue-50 text-blue-700 font-medium'
                    : 'text-gray-700 hover:bg-gray-50'
                }`}
                onClick={() => handleRoleChange(role.value)}
              >
                {currentRole === role.value && (
                  <Check className="mr-2 h-4 w-4" />
                )}
                <span>{role.label}</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
};

import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import {
  requireAuth,
  requireAdmin,
  sanitizeUser,
  networkDelay,
} from '../utils';

type ProfileBody = {
  email: string;
  firstName: string;
  lastName: string;
  bio: string;
};

type UserRoleBody = {
  role: 'ADMIN' | 'USER';
};

export const usersHandlers = [
  http.get(`${env.API_URL}/users`, async ({ cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const result = db.user
        .findMany({
          where: {
            teamId: {
              equals: user?.teamId,
            },
          },
        })
        .map(sanitizeUser);

      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/users/profile`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const data = (await request.json()) as ProfileBody;
      const result = db.user.update({
        where: {
          id: {
            equals: user?.id,
          },
        },
        data,
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/users/:userId/role`, async ({ request, cookies, params }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      requireAdmin(user);
      const userId = params.userId as string;
      const data = (await request.json()) as UserRoleBody;
      const result = db.user.update({
        where: {
          id: {
            equals: userId,
          },
        },
        data: { role: data.role },
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.delete(`${env.API_URL}/users/:userId`, async ({ cookies, params }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const userId = params.userId as string;
      requireAdmin(user);
      const result = db.user.delete({
        where: {
          id: {
            equals: userId,
          },
          teamId: {
            equals: user?.teamId,
          },
        },
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];

